solution_code:
def gradient(x):
    return 2 * (x - 3)


def minimise(start, learning_rate, steps):
    x = start
    for _ in range(steps):
        x = x - learning_rate * gradient(x)
    return x


print(minimise(start=0, learning_rate=0.1, steps=50))
